17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Map;
28	
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final AddressNormalizer addressNormalizer;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 AddressNormalizer addressNormalizer) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.addressNormalizer = addressNormalizer;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String address = addressNormalizer.normalize(owner.getAddress());
120	        if (address.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	        }
123	        owner.setAddress(address);
124	        String telephone = toE164(owner.getTelephone());
125	        if (telephone == null) {
126	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
127	        }
128	        owner.setTelephone(telephone);
129	        if (!owner.isPostcodeValid()) {
130	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	        }
132	        LocalDate effectiveDate = owner.getRegistrationDate() != null
133	            ? owner.getRegistrationDate() : LocalDate.now();
134	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
135	        if (isDailyLimitReached(owner.getRegistrationDate())) {
136	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
137	        }
138	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
139	        if (sharesHousehold) {
140	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
141	        }
142	        if (isDuplicate(owner)) {
143	            return new ResponseEntity<>(HttpStatus.CONFLICT);
144	        }
145	        if (isCityAtCapacity(owner.getCity())) {
146	            return new ResponseEntity<>(HttpStatus.CONFLICT);
147	        }
148	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
149	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
150	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
151	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
152	        this.clinicService.saveOwner(owner);
153	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
154	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        headers.setLocation(UriComponentsBuilder.newInstance()
157	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
158	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
159	    }
160	
161	    /**
162	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
163	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
164	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
165	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
166	     */
167	    private String nextCustomerCode(String city, String lastName) {
168	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
169	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
170	        int sequence = (int) this.clinicService.findAllOwners().stream()
171	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
172	            .count() + 1;
173	        return String.format("%s-%s-%04d", city3, last3, sequence);
174	    }
175	
176	    /**
177	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
178	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
179	     * (business-day) registration date of the owner being created, so owners are counted per
180	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
181	     */
182	    private boolean isDailyLimitReached(LocalDate day) {
183	        long count = this.clinicService.findAllOwners().stream()
184	            .filter(existing -> day.equals(existing.getRegistrationDate()))
185	            .count();
186	        return count >= 100;
187	    }
188	
189	    /**
190	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
191	     * more than 80 owners have already been created for the given business day. Counts the owners
192	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
193	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
194	     * warning.
195	     */
196	    private boolean isBulkSignup(LocalDate day) {
197	        long count = this.clinicService.findAllOwners().stream()
198	            .filter(existing -> day.equals(existing.getRegistrationDate()))
199	            .count();
200	        return count > 80;
201	    }
202	
203	    /**
204	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
205	     * advance it to the following Monday; a weekday is returned unchanged.
206	     */
207	    private LocalDate toBusinessDay(LocalDate date) {
208	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
209	            date = date.plusDays(1);
210	        }
211	        return date;
212	    }
213	
214	    /**
215	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
216	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
217	     */
218	    private boolean isCityAtCapacity(String city) {
219	        long count = this.clinicService.findAllOwners().stream()
220	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
221	            .count();
222	        return count >= 50;
223	    }
224	
225	    /**
226	     * The number of existing owners that already share the given firstName and lastName,
227	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
228	     * whitespace runs collapsed). Counted over the owners present before this create.
229	     */
230	    private int namesakeCount(String firstName, String lastName) {
231	        String candidateFirstName = normalizeName(firstName);
232	        String candidateLastName = normalizeName(lastName);
233	        return (int) this.clinicService.findAllOwners().stream()
234	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
235	                && normalizeName(existing.getLastName()).equals(candidateLastName))
236	            .count();
237	    }
238	
239	    /**
240	     * The number of members in this owner's household after this create: the count of existing
241	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
242	     * created. An owner with no household ({@code householdId == null}) is a household of one.
243	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
244	     * does not depend on the order in which household members were created.
245	     */
246	    private int householdSize(String householdId) {
247	        if (householdId == null) {
248	            return 1;
249	        }
250	        long existing = this.clinicService.findAllOwners().stream()
251	            .filter(other -> householdId.equals(other.getHouseholdId()))
252	            .count();
253	        return (int) existing + 1;
254	    }
255	
256	    /**
257	     * The number of national (subscriber) digits required for each known country calling
258	     * code, keyed by the code's digits (without the leading '+'). A number whose country
259	     * code appears here must carry exactly this many digits after the code, e.g. '+61'
260	     * requires 9 national digits and '+1' requires 10.
261	     */
262	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
263	        "1", 10,
264	        "61", 9);
265	
266	    /**
267	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
268	     * cannot form a valid E.164 number.
269	     *
270	     * <p>A leading '+' and country code are kept when present; otherwise country code
271	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
272	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
273	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
274	     * exactly the national-digit count that code requires (see
275	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}); otherwise it is rejected as invalid.
276	     */
277	    private String toE164(String telephone) {
278	        if (telephone == null) {
279	            return null;
280	        }
281	        boolean hasCountryCode = telephone.trim().startsWith("+");
282	        String digits = telephone.replaceAll("\\D", "");
283	        String e164;
284	        if (hasCountryCode) {
285	            e164 = digits;
286	        } else {
287	            if (digits.startsWith("0")) {
288	                digits = digits.substring(1);
289	            }
290	            e164 = "61" + digits;
291	        }
292	        if (e164.length() < 8 || e164.length() > 15) {
293	            return null;
294	        }
295	        if (!hasValidNationalLength(e164)) {
296	            return null;
297	        }
298	        return "+" + e164;
299	    }
300	
301	    /**
302	     * Whether the E.164 digit string (no leading '+') carries the national-number length
303	     * required by its country calling code. The longest matching known code wins; a number
304	     * whose country code is not recognised passes this check (its length is governed only by
305	     * the general 8-15 digit bound in {@link #toE164}).
306	     */
307	    private boolean hasValidNationalLength(String e164) {
308	        return NATIONAL_DIGITS_BY_COUNTRY.entrySet().stream()
309	            .filter(entry -> e164.startsWith(entry.getKey()))
310	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
311	            .map(entry -> e164.length() - entry.getKey().length() == entry.getValue())
312	            .orElse(true);
313	    }
314	
315	    /**
316	     * Whether the candidate owner duplicates an owner that already exists, and so must be
317	     * rejected with {@code 409 Conflict}. All duplicate detection is consolidated into a single
318	     * derived {@link Owner#getIdentityKey() identityKey} — the normalized telephone, email (or
319	     * empty) and householdId (or empty) joined with {@code '|'} — and an owner is a duplicate only
320	     * when its WHOLE identity key equals that of an existing owner. Because the telephone is part
321	     * of the key, two members of the same household with different telephones have different
322	     * identity keys and are both allowed; only an exact full-key match is a duplicate.
323	     */
324	    private boolean isDuplicate(Owner owner) {
325	        String identityKey = owner.getIdentityKey();
326	        return this.clinicService.findAllOwners().stream()
327	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
328	    }
329	
330	    /**
331	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
332	     * to a single space and lower-case. A null value normalizes to the empty string.
333	     */
334	    private String normalizeName(String value) {
335	        if (value == null) {
336	            return "";
337	        }
338	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
339	    }
340	
341	    /**
342	     * A stable shared identifier for the household formed by a given lastName and address.
343	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
344	     * lastName and address, so every owner sharing the same household is assigned the same
345	     * value regardless of the order in which they are created. Formatted as the first 12
346	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
347	     */
348	    private String householdId(String lastName, String address) {
349	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
350	        try {
351	            byte[] digest = MessageDigest.getInstance("SHA-256")
352	                .digest(key.getBytes(StandardCharsets.UTF_8));
353	            StringBuilder sb = new StringBuilder(digest.length * 2);
354	            for (byte b : digest) {
355	                sb.append(String.format("%02x", b));
356	            }
357	            return sb.substring(0, 12).toUpperCase();
358	        }
359	        catch (NoSuchAlgorithmException e) {
360	            throw new IllegalStateException("SHA-256 not available", e);
361	        }
362	    }
363	
364	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
365	    @Override
366	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
367	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
368	        if (currentOwner == null) {
369	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
370	        }
371	        currentOwner.setAddress(ownerFieldsDto.getAddress());
372	        currentOwner.setCity(ownerFieldsDto.getCity());
373	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
374	        currentOwner.setLastName(ownerFieldsDto.getLastName());
375	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
376	        this.clinicService.saveOwner(currentOwner);
377	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
378	    }
379	
380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Transactional
382	    @Override
383	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
384	        Owner owner = this.clinicService.findOwnerById(ownerId);
385	        if (owner == null) {
386	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
387	        }
388	        this.clinicService.deleteOwner(owner);
389	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
390	    }
391	
392	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
393	    @Override
394	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
395	        Owner owner = this.clinicService.findOwnerById(ownerId);
396	        if (owner == null) {
397	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	        }
399	        HttpHeaders headers = new HttpHeaders();
400	        Pet pet = petMapper.toPet(petFieldsDto);
401	        owner.setId(ownerId);
402	        pet.setOwner(owner);
403	        pet.getType().setName(null);
404	        this.clinicService.savePet(pet);
405	        PetDto petDto = petMapper.toPetDto(pet);
406	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
407	            .buildAndExpand(pet.getId()).toUri());
408	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
409	    }
410	
411	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
412	    @Override
413	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
414	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
415	        if (currentOwner != null) {
416	            Pet currentPet = this.clinicService.findPetById(petId);
417	            if (currentPet != null) {
418	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
419	                currentPet.setName(petFieldsDto.getName());
420	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
421	                this.clinicService.savePet(currentPet);
422	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
423	            }
424	        }
425	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
426	    }
427	
428	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
429	    @Override
430	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
431	        HttpHeaders headers = new HttpHeaders();
432	        Visit visit = visitMapper.toVisit(visitFieldsDto);
433	        Pet pet = new Pet();
434	        pet.setId(petId);
435	        visit.setPet(pet);
436	        this.clinicService.saveVisit(visit);
437	        VisitDto visitDto = visitMapper.toVisitDto(visit);
438	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
439	            .buildAndExpand(visit.getId()).toUri());
440	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
441	    }
442	
443	
444	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
445	    @Override
446	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
447	        Owner owner = this.clinicService.findOwnerById(ownerId);
448	        if (owner != null) {
449	            Pet pet = owner.getPet(petId);
450	            if (pet != null) {
451	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
452	            }
453	        }
454	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
455	    }
456	}
