175	    /**
176	     * The owner's initials: the upper-cased first letters of firstName and lastName,
177	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
178	     */
179	    public String getInitials() {
180	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
181	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
182	    }
