184	    /**
185	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
186	     * last two digits of the registrationDate year, e.g. {@code 'LON-SMI-0007-M26'}.
187	     */
188	    public String getMembershipNumber() {
189	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
190	    }
191	
192	    /** Fixed city-to-region table used to derive an owner's locality. */
193	    private static final Map<String, String> CITY_REGION = Map.of(
194	        "Sydney", "NSW",
195	        "Melbourne", "VIC",
196	        "Brisbane", "QLD");
197	
198	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
199	    public static final String UNKNOWN_REGION = "UNKNOWN";
